BEGIN;CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,body text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS notifications_identity_created_idx ON notifications(identity_id,created_at DESC);ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;ALTER TABLE notifications FORCE ROW LEVEL SECURITY;CREATE POLICY notifications_tenant_isolation ON notifications USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON notifications TO app_runtime;COMMIT;
